from textutil.slug import slugify


def test_accents():
    assert slugify("Crème brûlée à la carte") == "creme-brulee-a-la-carte"


def test_punctuation():
    assert slugify("Hello, World!") == "hello-world"


def test_spaces():
    assert slugify("  many   spaces  ") == "many-spaces"


def test_non_ascii_folded_not_dropped():
    # accented letters keep their plain base form (è -> e, û -> u, à -> a)
    assert slugify("Crème brûlée à la carte") == "creme-brulee-a-la-carte"

